tokens.light:
--paper:#F6F5F1; --paper-2:#FFFFFF; --card:#FFFFFF; --ink:#1A1D1B;
--muted:color-mix(in srgb,#1A1D1B 68%,#F6F5F1);
--faint:#6E6E6B;
--line:#E1DFD4; --line-soft:color-mix(in srgb,#E1DFD4 55%,#F6F5F1);
--raised:#FFFFFF; --sunk:color-mix(in srgb,#E1DFD4 42%,#F6F5F1);
--accent:#278453; --accent-2:#38D07F; --on-accent:#FFFFFF;
--accent-text:#257C4F;
--band:#12281D; --on-band:#FFFFFF;
--shadow-1:0 1px 2px rgba(26,29,27,.05),0 2px 10px rgba(26,29,27,.045);--shadow-2:0 2px 6px rgba(26,29,27,.06),0 18px 40px rgba(26,29,27,.10);
--wash-1:color-mix(in srgb,#278453 13%,transparent);
--wash-2:color-mix(in srgb,#12281D 8%,transparent);

tokens.dark:
--paper:#0E100F; --paper-2:#121513; --card:#171B19; --ink:#F0F2EE;
--muted:color-mix(in srgb,#F0F2EE 68%,#0E100F);
--faint:#818381;
--line:#2A322D; --line-soft:color-mix(in srgb,#2A322D 55%,#0E100F);
--raised:#171B19; --sunk:color-mix(in srgb,#2A322D 42%,#0E100F);
--accent:#38d07f; --accent-2:#2dbd70; --on-accent:#0E100F;
--accent-text:#38D07F;
--band:#171B19; --on-band:#F0F2EE;
--shadow-1:0 1px 2px rgba(0,0,0,.35);--shadow-2:0 18px 44px rgba(0,0,0,.5);
--wash-1:color-mix(in srgb,#38d07f 13%,transparent);
--wash-2:color-mix(in srgb,#171B19 8%,transparent);
